  if (strcmp(profile, "mixed") == 0)
    assert(stats.old_live_bytes == ((count + 63) / 64) * (old_header_size() + 3 * sizeof(Word)));
#endif
#ifdef USE_BOEHM
  GC_reachable_here(head); GC_reachable_here(anchor);
#endif
