           "\"tree_checksum_traversal_seconds\":%.9f,\"tree_final_major_plus_workload_cleanup_seconds\":%.9f", 
           tree_phase_construction_end - start,
           tree_phase_checksum_end - tree_phase_construction_end,
           end - tree_phase_final_major_start);
  } else {
    printf(",\"tree_phase_available\":false,\"tree_construction_including_root_setup_seconds\":null,"
           "\"tree_checksum_traversal_seconds\":null,\"tree_final_major_plus_workload_cleanup_seconds\":null");
  }
  printf("}\n");
  heap_destroy(); return 0;
}

