+/* The layout retains the words and mask of its prepared descriptor. The destination
+   is an exact live payload base from this heap and layout.
+   Fill the complete source array after allocation and root reloads; no collecting
+   call may intervene. This helper permits overlapping source and destination. */
+static inline __attribute__((always_inline)) void initialize_prepared(GcLayout layout, Word object,
+                                                                     const Word *fields, size_t count) {
+  assert(layout.epoch == gc_heap_epoch);
+  assert(layout.words > 0 && layout.words <= (SIZE_MAX - 3 * sizeof(Word)) / sizeof(Word));
+  assert(layout.words >= 64 || (layout.mask >> layout.words) == 0);
+  assert(count == layout.words && fields);
+  assert(object && !(object & (sizeof(Word) - 1)));
+#ifndef USE_BOEHM
+  Word *header = (Word *)object - 1;
+  assert((*header & ~(Word)7) == layout.info);
+#ifndef GC_MUTATE_BARRIER
+  int needs_barrier = !prepared_young(object) && !(*header & 1), has_young = 0;
+#endif
+#endif
+  for (size_t i = 0; i < count; ++i) {
+    Word value = fields[i]; int traced = i < 64 && ((layout.mask >> i) & 1);
+    assert(!prepared_pointer(value) || traced);
+#if !defined(USE_BOEHM) && !defined(GC_MUTATE_BARRIER)
+    if (needs_barrier && traced && prepared_young(value)) has_young = 1;
+#endif
+  }
+  memmove((void *)object, fields, count * sizeof(Word));
+#if !defined(USE_BOEHM) && !defined(GC_MUTATE_BARRIER)
+  if (has_young) remember_prepared(object);
+#endif
+}
 void heap_init(size_t nursery_bytes);
 void heap_destroy(void);
